    fn memory_grow(&mut self, delta: i32) -> i32 {
        let old_pages = (self.mem().len() / 65536) as u64;
        let new_pages = old_pages + (delta as u32 as u64);
        if new_pages > 65536 {
            return -1;
        }
        self.mem_mut().resize((new_pages as usize) * 65536, 0);
        old_pages as i32
    }

